function sumRange(dateFrom, dateTo) {
  let total = 0;
  const d0 = new Date(dateFrom), d1 = new Date(dateTo);
  for (let d = new Date(d0); d <= d1; d.setDate(d.getDate() + 1)) total += DATA.daily_ca[d.toISOString().slice(0, 10)] || 0;
  return total;
}
function shiftYear(iso, delta) { const d = new Date(iso); d.setFullYear(d.getFullYear() + delta); return d.toISOString().slice(0, 10); }

/* ============================================================================ NAV avec indicateur glissant */
function SlidingNav({ tab, onChange }) {
  const containerRef = useRef(null);
  const btnRefs = useRef({});
  const [indicator, setIndicator] = useState({ left: 0, width: 0 });

  useLayoutEffect(() => {
    const btn = btnRefs.current[tab];
    const container = containerRef.current;
    if (btn && container) {
      const cRect = container.getBoundingClientRect(), bRect = btn.getBoundingClientRect();
      setIndicator({ left: bRect.left - cRect.left, width: bRect.width });
    }
  }, [tab]);

  return (
    <nav ref={containerRef} className="hidden md:flex items-center gap-1 relative">
      <div className="absolute top-0 bottom-0 rounded-full" style={{
        left: indicator.left, width: indicator.width, background: `linear-gradient(135deg, ${ORANGE}, ${ORANGE_SOFT})`,
        boxShadow: `0 4px 14px -4px ${ORANGE}88`, transition: "left 0.4s cubic-bezier(.22,1,.36,1), width 0.4s cubic-bezier(.22,1,.36,1)", zIndex: 0,
      }} />
      {NAV.map((n) => (
        <button key={n.id} ref={(el) => (btnRefs.current[n.id] = el)} onClick={() => onChange(n.id)}
          className="relative flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-[13px] font-medium transition-colors duration-200"
          style={{ color: tab === n.id ? "#0A0908" : MUTED, zIndex: 1 }}>
          <n.icon size={14} strokeWidth={2} /> {n.label}
        </button>
      ))}
    </nav>
  );
}

